401	// ParseInterfacesIntoInstanceMap parses network interfaces into an InstanceMap
402	// This allows re-parsing the same network interface data with different subnet maps
403	// without making additional Azure API calls
404	func (c *Client) ParseInterfacesIntoInstanceMap(networkInterfaces []*armnetwork.Interface, subnets ipamTypes.SubnetMap) *ipamTypes.InstanceMap {
405		instances := ipamTypes.NewInstanceMap()
406	
407		for _, iface := range networkInterfaces {
408			if instanceID, azureInterface := parseInterface(iface, subnets, c.usePrimary); instanceID != "" {
409				instances.Update(instanceID, azureInterface)
410			}
411		}
412	
413		return instances
414	}
